// Parse jqGrid HTML — qualifying jobs: asbestos=green, JIS notes=red, WO=green
// Skip JIS notes=amber ("Not Required") or green (already done)
// NOTE: jqgrid_bg_* class is on the <td> tag, not cell inner HTML.

const fetchMeta = $('Pre-Works Fetch Summary').first().json || $('Fetch Pre-Works Table HTML (Playwright)').first().json || {};
const html = ($('Fetch Pre-Works Table HTML (Playwright)').first().json || {}).html || '';
const pages_scraped = fetchMeta.pages_scraped ?? null;
const rows_total = fetchMeta.rows_total ?? null;
const EASYBOP_BASE = 'https://easybop.co.uk';
const ASBESTOS_SUFFIX = '_wi_pw_24818_upload';
const JIS_SUFFIX = '_wi_pw_27059_notes';
const WO_SUFFIX = '_wi_pw_24819_upload';
const UPRN_SUFFIX = '_property_ref';
const ADDR_SUFFIX = '_address';
const CORF_SUFFIX = '_client_order_reference';

function cellClass(attrs) {
  const m = String(attrs || '').match(/class="([^"]*)"/i);
  if (!m) return '';
  return m[1].split(/\s+/).find(c => c.startsWith('jqgrid_bg_')) || '';
}

function cellHref(cell) {
  const blob = (cell?.attrs || '') + (cell?.inner || '');
  const m = blob.match(/href="([^"]+)"/i);
  if (!m) return null;
  const href = m[1].replace(/&amp;/g, '&');
  if (href.startsWith('http')) return href;
  return EASYBOP_BASE + '/' + href.replace(/^\//, '');
}

function cellTitle(attrs) {
  const m = String(attrs || '').match(/title="([^"]*)"/i);
  return m ? m[1].trim() : '';
}

const trRegex = /<tr[^>]+id="(\d+)"[^>]*>([\s\S]*?)<\/tr>/gi;
const jobs = [];
let trMatch;

while ((trMatch = trRegex.exec(html)) !== null) {
  const rowId = trMatch[1];
  const rowHtml = trMatch[2];
  const cells = {};
  const tdRegex = /<td([^>]+)>([\s\S]*?)<\/td>/gi;
  let tdMatch;
  while ((tdMatch = tdRegex.exec(rowHtml)) !== null) {
    const attrs = tdMatch[1];
    const keyMatch = attrs.match(/aria-describedby="([^"]+)"/i);
    if (!keyMatch) continue;
    cells[keyMatch[1]] = { attrs, inner: tdMatch[2] };
  }

  function getCell(suffix) {
    for (const [key, val] of Object.entries(cells)) {
      if (key.endsWith(suffix)) return val;
    }
    return null;
  }

  const uprnCell = getCell(UPRN_SUFFIX);
  const addrCell = getCell(ADDR_SUFFIX);
  const corfCell = getCell(CORF_SUFFIX);
  const asbCell = getCell(ASBESTOS_SUFFIX);
  const jisCell = getCell(JIS_SUFFIX);
  const woCell = getCell(WO_SUFFIX);
  if (!asbCell || !jisCell || !woCell) continue;

  const asbClass = cellClass(asbCell.attrs);
  const jisClass = cellClass(jisCell.attrs);
  const woClass = cellClass(woCell.attrs);

  if (jisClass.includes('amber')) continue;
  if (jisClass.includes('green')) continue;
  if (!jisClass.includes('red')) continue;
  if (!asbClass.includes('green')) continue;
  const woUrl = cellHref(woCell);
  if (!woClass.includes('green') || !woUrl) continue;

  jobs.push({
    pre_work_id: rowId,
    uprn: cellTitle(uprnCell?.attrs),
    address: cellTitle(addrCell?.attrs),
    asbestos_url: cellHref(asbCell),
    works_order_url: woUrl,
    client_order_reference: cellTitle(corfCell?.attrs) || '',
    jis_notes_class: jisClass,
    jis_notes_title: cellTitle(jisCell.attrs),
  });
}

console.log(`${fetchMeta.verify_message || ""} | Parsed ${jobs.length} qualifying jobs from pre-works table (pages_scraped=${pages_scraped}, rows_total=${rows_total})`);
return jobs.map(j => ({ json: j }));

const jisRows = $input.all().map(i => i.json);
const existingQ13Set = new Set(
  jisRows
    .map(r => (r['Q1.3'] || '').toString().trim().toLowerCase())
    .filter(Boolean)
);
console.log(`Loaded ${existingQ13Set.size} existing Q1.3 values from jis tab`);
return [{ json: { existingQ13Set: [...existingQ13Set] } }];

function normQ13(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 5) return String(parseInt(digits, 10));
  return t;
}
const jobs = $('Parse Pre-Works HTML').all().map(i => i.json);
const existingSet = new Set(
  ($('Build Existing Q1.3 Set').first().json.existingQ13Set || [])
    .map(normQ13)
    .filter(Boolean)
);
const sd = $getWorkflowStaticData('global');
sd.rowsWritten = 0;
return jobs.map(j => ({ json: { ...j, _existingQ13Set: [...existingSet] } }));

const job = $('Loop Each Job').item.json;
const address = job.address || '';
const uprn = job.uprn || '';

let fullText = '';
try {
  const ext = $('Extract Asbestos PDF Text').first().json || {};
  fullText = String(ext.text || ext.data || ext.content || '').trim();
} catch (e) {
  fullText = '';
}
if (!fullText) {
  const row = $input.first().json || {};
  fullText = String(row.text || row.data || row.content || '').trim();
}

function extractRegisterItems(text) {
  const registerHint = /\b(NAD|P\b|S0[1-3]|PTCA|No Access|Negative|Presumed|Asbestos Identified)\b/i;
  const locationHint = /(kitchen|bathroom|bedroom|hall|loft|garage|cupboard|landing|external|stairs|cellar)/i;
  const asbestosKeyword = /asbestos|ACM|NAD|PTCA/i;
  const lines = [];
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.length < 8) continue;
    if (registerHint.test(line) && (locationHint.test(line) || line.length > 25)) lines.push(line);
  }
  if (!lines.length) {
    for (const raw of text.split(/\r?\n/)) {
      const line = raw.trim();
      if (asbestosKeyword.test(line) && line.length > 10) lines.push(line);
    }
  }
  const seen = new Set();
  const out = [];
  for (const line of lines) {
    const key = line.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(line);
  }
  return out.slice(0, 40).join('\n');
}

function buildSummary(text, items) {
  const head = text.slice(0, 2500).replace(/\s+/g, ' ').trim();
  const parts = [];
  if (address) parts.push(`Property: ${address}`);
  if (uprn) parts.push(`UPRN: ${uprn}`);
  if (items) {
    const n = items.split(/\r?\n/).filter((l) => l.trim()).length;
    parts.push(`${n} ACM register line(s) parsed`);
  }
  if (/no asbestos|nad only|no acm/i.test(head)) parts.push('No ACM identified in accessed areas');
  else if (/asbestos|acm|ptca|presumed/i.test(head)) parts.push('Asbestos/ACM references found');
  if (head) parts.push(head.slice(0, 400));
  return parts.join('. ');
}

function inferStatus(text, items) {
  const blob = `${text}\n${items}`.toLowerCase();
  if (/\b(ptca|presumed|s0[1-3]|asbestos identified|strongly presumed)\b/.test(blob)) return 'PTCA/ACM';
  if (/\b(nad|negative|not identified|negatively sampled)\b/.test(blob)) return 'NAD';
  if (/\bno access|exercise caution\b/.test(blob)) return 'No Access';
  return 'Report on file';
}

if (!fullText) {
  const parts = [];
  if (address) parts.push(`Property: ${address}`);
  parts.push('PDF on file; text extraction returned empty (scanned PDF or extract error)');
  return [{
    json: {
      success: true,
      asbestos_status: 'Report on file',
      asbestos_summary: parts.join('. '),
      asbestos_items: '',
      error: 'no_text_extracted',
      parse_source: 'n8n_extract_from_file',
    },
  }];
}

const items = extractRegisterItems(fullText);
return [{
  json: {
    success: true,
    asbestos_status: inferStatus(fullText, items),
    asbestos_summary: buildSummary(fullText, items),
    asbestos_items: items,
    text_length: fullText.length,
    parse_source: 'n8n_extract_from_file',
  },
}];

const item = $input.first();
const job = $('Loop Each Job').item.json;

async function msgBuffer() {
  const bin = item.binary || {};
  const keys = ['works_order', ...Object.keys(bin).filter(k => k !== 'works_order')];
  for (const key of keys) {
    if (!bin[key]) continue;
    try {
      const buf = await this.helpers.getBinaryDataBuffer(0, key);
      if (buf && buf.length > 0) return { buf, key };
    } catch (e) {
      const inline = bin[key]?.data;
      if (typeof inline === 'string' && inline.length > 0) {
        const buf = Buffer.from(inline, 'base64');
        if (buf.length > 0) return { buf, key };
      }
    }
  }
  const b64 = item.json?.data;
  if (typeof b64 === 'string' && b64.length > 0) {
    return { buf: Buffer.from(b64, 'base64'), key: 'json.data' };
  }
  return null;
}

const hit = await msgBuffer();
if (!hit || !hit.buf || hit.buf.length < 256) {
  throw new Error('Download Works Order returned no usable file bytes');
}
const buf = hit.buf;

const head = buf.slice(0, 512).toString('utf-8').toLowerCase();
if (head.includes('<html') || head.includes('please log in')) {
  throw new Error('EasyBOP returned HTML — session cookies may have expired');
}

const woUrl = job.works_order_url || '';
let filename = 'works_order.msg';
const m1 = woUrl.match(/filename_orig=([^&]+)/i);
if (m1) filename = decodeURIComponent(m1[1]);
else {
  const m2 = woUrl.match(/([^/?]+\.msg)/i);
  if (m2) filename = m2[1];
}
if (!filename.toLowerCase().endsWith('.msg')) filename += '.msg';

const msg_base64 = buf.toString('base64');
if (msg_base64.length < 512) {
  throw new Error(`Encoded works order too small (${msg_base64.length} base64 chars)`);
}

return [{
  json: {
    msg_base64,
    filename,
    msg_bytes: buf.length,
    _binary_key: hit.key,
  },
}];

const job = $input.first().json;
const ab = $('Parse Asbestos PDF').first().json || {};
return [{ json: {
  ...job,
  asbestos_status: ab.asbestos_status ?? 'Report on file',
  asbestos_summary: ab.asbestos_summary ?? '',
  asbestos_items: ab.asbestos_items ?? '',
} }];

