parameters.jsCode:
const aiRaw = $('AI Extract JIS (Q1-Q5)').first().json;
const job = $('Loop Each Job').item.json;
const ab = $('Parse Asbestos PDF').first().json || {};
const apptFormatted = $('Format Appointment Row').first().json || {};
const prep = $('Prepare Appointment AI Input').first().json || {};

let ai = {};
try {
  const content = aiRaw.output?.[0]?.content?.[0]?.text || aiRaw.message?.content || '{}';
  ai = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  ai = aiRaw;
}

function s(v) { return (v == null || v === 'null') ? '' : String(v).trim(); }

const addList = Array.isArray(ai.Q5_1_add_codes) ? ai.Q5_1_add_codes.filter(Boolean) : ['Not Answered'];
const omitList = Array.isArray(ai.Q5_2_omit_codes) ? ai.Q5_2_omit_codes.filter(Boolean) : ['Not Answered'];
const q51 = addList.join(', ') || 'Not Answered';
const q52 = omitList.join(', ') || 'Not Answered';
const reason5 = s(ai.reason_5);
const qsTask = `Added SORs: ${addList.join(', ') || 'none'}. Omitted SORs: ${omitList.join(', ') || 'none'}. Why: ${reason5 || 'AI scope-based review.'}`;
const q32 = Array.isArray(ai.Q3_2_scaffold_details) ? ai.Q3_2_scaffold_details[0] || '' : s(ai.Q3_2_scaffold_details);

let q13 = s(job.client_order_reference) || s(ai.Q1_3_job_no);
const prepBundle = $('Check Q1.3 from WO Subject').first().json || $('Prepare for AI').first().json || prep;
if (!q13) q13 = s(prepBundle.q13_resolved) || s(prep.job_no) || '';
if (!q13) {
  const m = String(prep.subject || prepBundle.subject || '').match(/(\d+\/\d+)/);
  if (m) q13 = m[1];
}
if (!q13) {
  return [{ json: { _skipped: true, reason: 'no_q13', pre_work_id: job.pre_work_id } }];
}

const uprn = s(ai.uprn) || job.uprn || '';
const apptRow = {
  UPRN: apptFormatted.UPRN || uprn,
  '7.1': s(apptFormatted['7.1']),
  '7.2': s(apptFormatted['7.2']),
  Trade_1: s(apptFormatted.Trade_1),
  Hours_1: s(apptFormatted.Hours_1),
  Notes_1: s(apptFormatted.Notes_1),
  '8.1': s(apptFormatted['8.1']),
  '8.2': s(apptFormatted['8.2']),
  Trade_2: s(apptFormatted.Trade_2),
  Hours_2: s(apptFormatted.Hours_2),
  Notes_2: s(apptFormatted.Notes_2),
  '9.1': s(apptFormatted['9.1']),
  '9.2': s(apptFormatted['9.2']),
  Trade_3: s(apptFormatted.Trade_3),
  Hours_3: s(apptFormatted.Hours_3),
  Notes_3: s(apptFormatted.Notes_3),
  '10.1': s(apptFormatted['10.1']),
  '10.2': s(apptFormatted['10.2']),
  Trade_4: s(apptFormatted.Trade_4),
  Hours_4: s(apptFormatted.Hours_4),
  Notes_4: s(apptFormatted.Notes_4),
  '11.1': s(apptFormatted['11.1']),
  '11.2': s(apptFormatted['11.2']),
  Trade_5: s(apptFormatted.Trade_5),
  Hours_5: s(apptFormatted.Hours_5),
  Notes_5: s(apptFormatted.Notes_5),
};

const apptCount = apptFormatted._appointment_count || 0;
const has_appointment = apptCount > 0 || !!apptRow.Trade_1;

const jisRow = {
  'Q1.1': s(ai.Q1_1_start_within),
  'Q1.2': s(ai.Q1_2_address),
  'Q1.3': q13,
  'Q1.4': 'AI',
  'Q1.5': s(ai.Q1_5_bcc_surveyor),
  'Q1.6': s(ai.Q1_6_work_description),
  'Q2.1': s(ai.Q2_1_asbestos_survey_required) || 'yes',
  'Q2.2': s(ai.Q2_2_asbestos_survey_on_easybop),
  'Q3.1': s(ai.Q3_1_scaffold_required),
  'Q3.2': q32,
  'Q4.1': s(ai.Q4_1_asbestos_removal_or_shadow_vac_before_start),
  'Q4.2': s(ai.Q4_2_details_asbestos_removal),
  'Q5.1': q51,
  'Q5.2': q52,
  'QS-Task': qsTask,
  'Asbestos Status': s(ab.asbestos_status) || 'Report on file',
  'jis_uploaded': false,
};

return [{ json: {
  _skipped: false,
  pre_work_id: job.pre_work_id,
  address: job.address,
  uprn,
  q13,
  jisRow,
  apptRow,
  has_appointment,
  _appointment_count: apptCount,
} }];

function normDocKey(raw) {
  if (raw === null || raw === undefined) return null;
  const digits = String(raw).replace(/[^0-9]/g, '');
  if (!digits) return null;
  const last6 = digits.length >= 6 ? digits.slice(-6) : digits.padStart(6, '0');
  return last6.padStart(6, '0');
}
function pickCol(row, names) {
  for (const n of names) {
    if (row[n] !== undefined && row[n] !== null && String(row[n]).trim() !== '') return row[n];
  }
  return null;
}
const items = $input.all();
const smvLookup = {};
for (const item of items) {
  const row = item.json || {};
  const docCode = pickCol(row, ['Document Code', 'Document code', 'DOCUMENT CODE', 'Reference', 'REFERENCE']);
  if (docCode == null) continue;
  const key = normDocKey(docCode);
  if (!key) continue;
  const detailed = pickCol(row, ['Detailed Description', 'Detailed description', 'DETAILED DESCRIPTION']);
  smvLookup[key] = { documentCode: String(docCode).trim(), detailedDescription: detailed != null ? String(detailed).trim() : '' };
}
return [{ json: { smvLookup, smv_unique_keys: Object.keys(smvLookup).length } }];

const prep = $('Prepare for AI').first().json;
const smvLookup = ($('Build SMV Lookup').first().json || {}).smvLookup || {};

function normDocKey(raw) {
  if (raw == null) return null;
  const digits = String(raw).replace(/[^0-9]/g, '');
  if (!digits) return null;
  const last6 = digits.length >= 6 ? digits.slice(-6) : digits;
  return last6.padStart(6, '0');
}

function parseBoqFromText(plain) {
  const lines = String(plain || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const boq = [];
  const codeRe = /^(\d{1,3}[A-Z]{2}\d{4,6})$/i;
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(codeRe);
    if (!m) continue;
    const code = m[1].toUpperCase();
    let qty = 1;
    let location = '';
    for (let j = i + 1; j < Math.min(i + 12, lines.length); j++) {
      if (/^\d+(\.\d+)?$/.test(lines[j]) && qty === 1) {
        qty = parseFloat(lines[j]) || 1;
        continue;
      }
      if (/^(KITCH|BATHRM|BED\d|LIVROOM|HALL|LOFT|EXT|LANDING|STAIR)/i.test(lines[j])) {
        location = lines[j].toUpperCase();
        break;
      }
    }
    boq.push({ code, quantity: qty, location });
  }
  return boq;
}

function parseQtyFromContext(code, plain, boqLines) {
  const codeNorm = String(code || '').replace(/\s+/g, '').toUpperCase();
  const hit = (boqLines || []).find(ln => String(ln.code || '').replace(/\s+/g, '').toUpperCase() === codeNorm);
  if (hit && hit.quantity != null) return Math.max(1, parseFloat(hit.quantity) || 1);
  const c = codeNorm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(c + '[^\\d]{0,40}(\\d+(?:\\.\\d+)?)', 'i');
  const m = String(plain || '').match(re);
  return m ? parseFloat(m[1]) : 1;
}

function smvMetaForCode(code, plain, boqLines) {
  const key = normDocKey(code);
  const row = key ? smvLookup[key] : null;
  const detailed = row ? String(row.detailedDescription || '').trim() : '';
  const isSub = /^subcontract/i.test(detailed);
  const smvNum = !isSub && detailed && !/^error/i.test(detailed) ? parseFloat(detailed.replace(/[^0-9.]/g, '')) : NaN;
  return {
    code: String(code).trim(),
    document_code_key: key,
    quantity: parseQtyFromContext(code, plain, boqLines),
    detailed_description: detailed || null,
    smv_raw: Number.isFinite(smvNum) ? smvNum : null,
    is_subcontract: isSub,
  };
}

function buildAppointmentPlanningHints(plain, description, asbestosItems) {
  const text = `${plain || ''} ${description || ''}`.toLowerCase();
  const hints = [];
  const hasRender = /\brender(ing)?\b|scratch coat|top coat|hack off.*render|defective render/i.test(text);
  const hasPlaster = /\bplaster\b|skim|bonding|reboard|plasterboard|hack off.*plaster|replaster|dub out/i.test(text);
  const hasDecorate = /\bemulsion\b|decorat|mist coat|paint\b|biocheck|halophen|bactdet/i.test(text);
  const hasDehumid = /de-?humidifier|dry out|fully dry/i.test(text);
  const hasTiles = /wall tiles|tile/i.test(text);
  if (hasDehumid) {
    hints.push('SPLIT REQUIRED: Dehumidifier week hire is its own visit BEFORE hack-off/plaster in bathroom');
  }
  if (hasRender) {
    hints.push('SPLIT REQUIRED: Visit 1 = hack off / scratch coat only — RETURN FOLLOWING DAY TO TOP COAT');
    hints.push('SPLIT REQUIRED: Top coat render = separate visit');
  }
  if (hasPlaster && (hasRender || hasTiles)) {
    hints.push('SPLIT REQUIRED: Plaster/skim AFTER render/tiles prep dry — ALLOW TO DRY 3 DAYS between wet-trade visits');
  } else if (hasPlaster) {
    hints.push('Hack off + dub out + skim are often SEPARATE visits with drying between');
  }
  if (hasDecorate && (hasPlaster || hasRender)) {
    hints.push('SPLIT REQUIRED: Decorator (Bactdet/Halophen/emulsion) LAST after plaster dry 3–4 days');
  }
  if (hints.length === 0) {
    hints.push('Split by trade and drying time — use up to 5 appointments; do not merge kitchen, bathroom wet trades, and decorating into one visit');
  }
  const acmText = String(asbestosItems || '').toLowerCase();
  if (acmText && /\bptca\b|presumed|asbestos identified|s0[1-3]/i.test(acmText)) {
  if (/hack off|replaster|tiles|reboard/i.test(text)) {
      hints.unshift('ASBESTOS: sequence intrusive bathroom/kitchen works per register — shadow vac bullets under trade, not separate appt unless full removal');
    }
  }
  return hints;
}

const plainText = prep.body_text || '';
const boqLines = parseBoqFromText(plainText);
const sorRegex = /\b\d{1,3}\s*[A-Z]{2}\s*\d{4,6}\b/gi;
const fromBoq = boqLines.map(ln => ln.code);
const fromText = (plainText.match(sorRegex) || []).map(s => s.replace(/\s+/g, ''));
const foundSors = [...new Set([...fromBoq, ...fromText].map(s => String(s).replace(/\s+/g, '').toUpperCase()).filter(Boolean))];
const sorLines = foundSors.map(code => smvMetaForCode(code, plainText, boqLines));
const jobRefMatch = (prep.subject || '').match(/(\d+\/\d+)/);
const worksOrderRef = jobRefMatch ? jobRefMatch[1] : '';

return [{
  json: {
    ...prep,
    body_plain_text: plainText,
    UPRN: prep.uprn || '',
    job_no: worksOrderRef,
    works_order_extracted: {
      works_order_ref: worksOrderRef,
      uprn: prep.uprn || '',
      address: prep.address || '',
      site_address: prep.address || '',
      description: plainText.slice(0, 800),
    },
    found_sors_in_email: foundSors,
    boq_sor_lines: boqLines,
    sor_lines_with_smv: sorLines,
    appointment_planning_hints: buildAppointmentPlanningHints(plainText, '', prep.asbestos_items || ''),
  },
}];

