function unwrapAI(r) {
  if (!r || typeof r !== 'object') return {};
  if (r?.output?.[0]?.content?.[0]?.text !== undefined) {
    const t = r.output[0].content[0].text;
    if (typeof t === 'object' && t !== null) return t;
    if (typeof t === 'string') {
      try {
        return JSON.parse(t);
      } catch (e) {}
    }
  }
  const cc = r?.message?.content ?? r?.choices?.[0]?.message?.content ?? null;
  if (cc !== null) {
    if (typeof cc === 'object') return cc;
    if (typeof cc === 'string') {
      try {
        return JSON.parse(cc);
      } catch (e) {}
    }
  }
  if (r.appointments !== undefined) return r;
  return {};
}

function normDocKey(raw) {
  if (raw == null) return null;
  const digits = String(raw).replace(/[^0-9]/g, '');
  if (!digits) return null;
  const last6 = digits.length >= 6 ? digits.slice(-6) : digits;
  return last6.padStart(6, '0');
}

function parseSmv(raw) {
  if (raw == null) return null;
  const s = String(raw).trim();
  if (!s || /^subcontract/i.test(s)) return null;
  if (/^error:#?n\/a/i.test(s)) return null;
  const n = parseFloat(s.replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : null;
}

function roundUp15(mins) {
  if (!Number.isFinite(mins) || mins <= 0) return 0;
  return Math.ceil(mins / 15) * 15;
}

/** Admin sheet uses whole hours (e.g. 4, 3) not "7 hrs 15 mins". */
function formatHoursForSheet(totalMins) {
  if (!Number.isFinite(totalMins) || totalMins <= 0) return '';
  const rounded = roundUp15(totalMins);
  const hours = Math.ceil(rounded / 60);
  return String(Math.max(1, hours));
}

function normalizeHoursOutput(raw, sorRefs, smvLookup) {
  if (raw == null || raw === '') {
    return calcHoursFromSors(sorRefs, smvLookup, '');
  }
  const s = String(raw).trim();
  if (/^subcontract/i.test(s)) return s;
  if (/^time tbc/i.test(s)) return s;
  const plainNum = s.match(/^(\d+(?:\.\d+)?)\s*$/);
  if (plainNum) return String(Math.max(1, Math.ceil(parseFloat(plainNum[1]))));
  const hrMatch = s.match(/(\d+)\s*hrs?/i);
  if (hrMatch) return hrMatch[1];
  const minMatch = s.match(/(\d+)\s*mins?/i);
  if (minMatch && !hrMatch) {
    return formatHoursForSheet(parseInt(minMatch[1], 10));
  }
  return calcHoursFromSors(sorRefs, smvLookup, s);
}

function calcHoursFromSors(sorRefs, smvLookup, fallbackHours) {
  let productive = 0;
  let anySub = false;
  let anyTbc = false;
  for (const s of sorRefs || []) {
    const code = s.code || s.sor_code || s;
    const key = normDocKey(code);
    const qty = Math.max(1, parseFloat(s.quantity) || 1);
    const row = key ? smvLookup[key] : null;
    const smvRaw = row ? parseSmv(row.detailedDescription) : null;
    if (row && /^subcontract/i.test(String(row.detailedDescription || ''))) {
      anySub = true;
      continue;
    }
    if (smvRaw == null) {
      anyTbc = true;
      continue;
    }
    productive += smvRaw * 0.8 * qty;
  }
  if (anySub && productive === 0) return 'Subcontract - book separately';
  const total = productive + 30;
  if (productive === 0 && anyTbc) return fallbackHours || 'Time TBC';
  return formatHoursForSheet(total);
}

function yesNo(v) {
  if (v === true || v === 1) return 'yes';
  const s = String(v ?? '')
